// Falla en voz alta si el servidor rechaza el resumen o si algún idioma falla: así aparece como ejecución con error en n8n.
const r = $json;
if (!r.success) throw new Error('El servidor rechazó el resumen: ' + JSON.stringify(r).slice(0, 300));
const resultados = r.results || {};
// 'skipped' por pocas notas o ya enviado es normal; por falta de dirección postal es un error de configuración
const malos = Object.entries(resultados).filter(([, x]) => ['failed', 'error'].includes(x.status) || x.reason === 'missing_postal_address');
if (malos.length) throw new Error('Falló el resumen en: ' + malos.map(([l, x]) => l + ' (' + (x.error || x.status) + ')').join(', '));
return { json: { resumen: Object.fromEntries(Object.entries(resultados).map(([l, x]) => [l, { status: x.status, articulos: x.count, motivo: x.reason }])) } };
